; c09_csr_read -- EXEC_CSR READ8 / READ_BUF and MAIN_CSR_DATA_BUF
; Layer-1 conformance test (generated by conformance/make_conformance.py: edit that, not this file).
; Checks: CsrOneByteDesc READ8 and its destination pointer; CsrMultiByteDesc (page, length, pointer); MOV from MAIN_CSR_DATA_BUF
; Results go to the result CSRs RES + n (conf_defs.inc); the last write is RES_DONE = 0xA5. Expected values: c09_csr_read.expected.csv
.include "conf_defs.inc"
.main
    EXEC_CSR WRITE8 RES + 16, 0x3C
    EXEC_CSR READ8  RES + 16 -> MAIN_CSR_DATA_BUF[2]
    MOV MAIN_CSR_DATA_BUF[2..2] -> MAIN_SCRATCHPAD[0..0]
    EXEC_CSR WRITE_SP RES + 0, len=1, ptr=0
    EXEC_CSR WRITE8 RES + 20, 0xA1
    EXEC_CSR WRITE8 RES + 21, 0xA2
    EXEC_CSR WRITE8 RES + 22, 0xA3
    EXEC_CSR READ_BUF RES + 20, len=3, ptr=5
    MOV MAIN_CSR_DATA_BUF[5..7] -> MAIN_SCRATCHPAD[4..6]
    EXEC_CSR WRITE_SP RES + 4, len=3, ptr=4
    EXEC_CSR WRITE8 RES_DONE, 0xA5          ; the last write: everything above is there
done:
    JMP done
